import{_ as e,a0 as n,w as p,s as r,ao as d,I as a,x as t,a1 as o,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"命令列中的世界盃 | LCTT x X-CMD","titleTemplate":false,"description":"命令列中的世界盃 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列中的世界盃 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列中的世界盃 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180627 World Cup football on the command line","title":"命令列中的世界盃","tag":"201807","desc":""},"relativePath":"201807/20180627 World Cup football on the command line.md","filePath":"[post].md"}'),u={name:"201807/20180627 World Cup football on the command line.md"};function g(f,l,b,m,k,h){const s=n("Link");return p(),r("div",null,[l[18]||(l[18]=d('<h1 id="命令列中的世界盃" tabindex="-1">命令列中的世界盃 <a class="header-anchor" href="#命令列中的世界盃" aria-label="Permalink to “命令列中的世界盃”">​</a></h1><p><img src="https://i2.wp.com/www.linuxlinks.com/wp-content/uploads/2018/06/football-wc2018.jpg?resize=700%2C450&amp;ssl=1" alt=""></p><p>足球始終在我們身邊。即使我們國家的隊伍已經出局（LCTT 譯註：顯然這不是指我們國家，因為我們根本沒有入局……），我還是想知道球賽比分。目前， 國際足聯世界盃是世界上最大的足球錦標賽，2018 屆是由俄羅斯主辦的。每屆世界盃都有一些足球強國未能取得參賽資格（LCTT 譯註：我要吐槽麼？）。意大利和荷蘭就無緣本次世界盃。但是即使在未參加比賽的國家，追蹤關注最新比分也成為了一種儀式。我希望能及時瞭解這個世界級的重大賽事最新比分的變化，而不用去搜索不同的網站。</p><p>如果你很喜歡命令列，那麼有更好的方法用一個小型命令列程序追蹤最新的世界盃比分和排名。讓我們看一看最熱門的可用的球賽趨勢分析程序之一，它叫作 football-cli。</p><p>football-cli 不是一個開創性的應用程序。這幾年，有許多命令列工具可以讓你瞭解到最新的球賽比分和賽事排名。例如，我是 soccer-cli （Python 寫的）和 App-football （Perl 寫的）的重度用户。但我總是在尋找新的趨勢分析應用，而 football-cli 在某些方面脱穎而出。</p><p>football-cli 是 JavaScript 開發的，由 Manraj Singh 編寫，它是開源的軟件。基於 MIT 許可證發佈，用 npm（JavaScript 包管理器）安裝十分簡單。那麼，讓我們直接行動吧！</p><p>該應用程序提供了命令以獲取過去及現在的賽事得分、查看聯賽和球隊之前和將要進行的賽事。它也會顯示某一特定聯賽的排名。有一條指令可以列出程序所支持的不同賽事。我們不妨從最後一個條指令開始。</p><p>在 shell 提示符下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>luke@ganges:~$ football lists</span></span></code></pre></div><p><img src="https://i2.wp.com/www.linuxlinks.com/wp-content/uploads/2018/06/football-lists.png?resize=595%2C696&amp;ssl=1" alt="球賽列表"></p><p>世界盃被列在最下方，我錯過了昨天的比賽，所以為了瞭解比分，我在 shell 提示下輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>luke@ganges:~$ football scores</span></span></code></pre></div><p><img src="https://i2.wp.com/www.linuxlinks.com/wp-content/uploads/2018/06/football-wc-22.png?resize=634%2C75&amp;ssl=1" alt="football-wc-22"></p><p>現在，我想看看目前的世界盃小組排名。很簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>luke@ganges:~$ football standings -l WC</span></span></code></pre></div><p>下面是輸出的一個片段：</p><p><img src="https://i0.wp.com/www.linuxlinks.com/wp-content/uploads/2018/06/football-wc-table.png?resize=750%2C581&amp;ssl=1" alt="football-wc-biaoge"></p><p>你們當中眼尖的可能會注意到這裏有一個錯誤。比如比利時看上去領先於 G 組，但這是不正確的，比利時和英格蘭（截稿前）在得分上打平。在這種情況下，紀律好的隊伍排名更高。英格蘭收到兩張黃牌，而比利時收到三張，因此，英格蘭應當名列榜首。</p><p>假設我想知道利物浦 90 天前英超聯賽的結果，那麼:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>luke@ganges:~$ football fixtures -l PL -d 90 -t &quot;Liverpool&quot;</span></span></code></pre></div><p><img src="https://i1.wp.com/www.linuxlinks.com/wp-content/uploads/2018/06/football-Liverpool.png?resize=749%2C131&amp;ssl=1" alt="足球-利物浦"></p><p>我發現這個程序非常方便。它用一種清晰、整潔而有吸引力的方式顯示分數和排名。當歐洲聯賽再次開始時，它就更有用了。（事實上 2018-19 冠軍聯賽已經在進行中）！</p>',22)),a("p",null,[l[1]||(l[1]=t("這幾個示例讓大家對 football-cli 的實用性有了更深的體會。想要了解更多，請轉至開發者的 ",-1)),o(s,{href:"https://github.com/ManrajGrover/football-cli"},{default:i(()=>[...l[0]||(l[0]=[t("GitHub 頁面",-1)])]),_:1}),l[2]||(l[2]=t("。足球 ＋ 命令列 ＝ football-cli。",-1))]),l[19]||(l[19]=a("p",null,"如同許多類似的工具一樣，該軟件從 football-data.org 獲取相關數據。這項服務以機器可讀的方式為所有歐洲主要聯賽提供數據，包括比賽、球隊、球員、結果等等。所有這些信息都是以 JOSN 形式通過一個易於使用的 RESTful API 提供的。",-1)),l[20]||(l[20]=a("hr",null,null,-1)),a("p",null,[l[4]||(l[4]=t("via: ",-1)),o(s,{href:"https://www.linuxlinks.com/football-cli-world-cup-football-on-the-command-line/"},{default:i(()=>[...l[3]||(l[3]=[t("https://www.linuxlinks.com/football-cli-world-cup-football-on-the-command-line/",-1)])]),_:1})]),a("p",null,[l[9]||(l[9]=t("作者：",-1)),o(s,{href:"https://www.linuxlinks.com/author/luke-baker/"},{default:i(()=>[...l[5]||(l[5]=[t("Luke Baker",-1)])]),_:1}),l[10]||(l[10]=t(" 選題：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...l[6]||(l[6]=[t("lujun9972",-1)])]),_:1}),l[11]||(l[11]=t(" 譯者：",-1)),o(s,{href:"https://github.com/ZenMoore"},{default:i(()=>[...l[7]||(l[7]=[t("ZenMoore",-1)])]),_:1}),l[12]||(l[12]=t(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:i(()=>[...l[8]||(l[8]=[t("wxy",-1)])]),_:1})]),a("p",null,[l[15]||(l[15]=t("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...l[13]||(l[13]=[t("LCTT",-1)])]),_:1}),l[16]||(l[16]=t(" 原創編譯，",-1)),o(s,{href:"https://linux.cn/"},{default:i(()=>[...l[14]||(l[14]=[t("Linux中國",-1)])]),_:1}),l[17]||(l[17]=t(" 榮譽推出",-1))])])}const T=e(u,[["render",g]]);export{c as __pageData,T as default};
